import pandas as pd, numpy as np

df=pd.read_csv('/app/benchmark/data.csv')
month_map={'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}

def parse_my(s):
    if not isinstance(s,str):
        return pd.NaT
    try:
        m,y=s.split('-')
        if m=='Unknown':
            return pd.NaT
        return pd.Timestamp(int(y), month_map[m], 1)
    except Exception:
        return pd.NaT

df['month_dt']=df['month_year'].map(parse_my)
mt=df.dropna(subset=['month_dt']).copy()
mt['major_topic']=mt['major_topic'].fillna('Unindexed/None')
mt=mt[mt['major_topic']!='Unindexed/None']
monthly_idx=pd.date_range(mt['month_dt'].min(), mt['month_dt'].max(), freq='MS')
res=[]
for topic,g in mt.groupby('major_topic'):
    s=g.groupby('month_dt').size().reindex(monthly_idx, fill_value=0).astype(float)
    prev=s.shift(1)
    growth=(s-prev)/prev
    # filters for stability
    growth= growth.where(prev>=5)
    mx=growth.max(skipna=True)
    if pd.notna(mx) and mx>0:
        res.append((topic,float(mx), int((s.sum()))))
res=pd.DataFrame(res, columns=['major_topic','max_mom_growth','total']).sort_values('max_mom_growth', ascending=False)
print('count topics with positive max mom growth', len(res))
print(res.head(20))
PY"}

